export function taskLabel(name: string, completed: boolean): string {
  return (completed ? '[x] ' : '[ ] ') + name;
}

import assert from 'node:assert/strict';
import {test} from 'node:test';
import {taskLabel} from '../src/labels.ts';

test('completed task gets [x] prefix', () => {
  assert.equal(taskLabel('review PR', true), '[x] review PR');
});

test('incomplete task keeps [ ] prefix', () => {
  assert.equal(taskLabel('review PR', false), '[ ] review PR');
});

test('preserves name exactly with special characters and whitespace', () => {
  assert.equal(taskLabel('  spaced task  ', true), '[x]   spaced task  ');
  assert.equal(taskLabel('', true), '[x] ');
  assert.equal(taskLabel('', false), '[ ] ');
  assert.equal(taskLabel('[ ] nested [x]', true), '[x] [ ] nested [x]');
});
